# Let's use a greedy approach to find the maximum number of edges for girth 7 and n=19.
import random

def get_max_edges():
    n = 19
    edges = []
    # Try to add edges randomly while maintaining girth >= 7
    # This is a heuristic.

    def has_cycle_less_than_7(n, edges):
        import collections
        adj = collections.defaultdict(list)
        for u, v in edges:
            adj[u].append(v)
            adj[v].append(u)

        for i in range(n):
            dist = {i: 0}
            parent = {i: None}
            queue = collections.deque([i])
            while queue:
                u = queue.popleft()
                for v in adj[u]:
                    if v not in dist:
                        dist[v] = dist[u] + 1
                        parent[v] = u
                        queue.append(v)
                    elif v != parent[u]:
                        cycle_len = dist[u] + dist[v] + 1
                        if cycle_len < 7:
                            return True
        return False

    all_possible_edges = []
    for i in range(n):
        for j in range(i + 1, n):
            all_possible_edges.append((i, j))

    random.shuffle(all_possible_edges)

    current_edges = []
    for edge in all_possible_edges:
        current_edges.append(edge)
        if has_cycle_less_than_7(n, current_edges):
            current_edges.pop()

    return len(current_edges), current_edges

max_edges = 0
for _ in range(100):
    m, edges = get_max_edges()
    if m > max_edges:
        max_edges = m

print(max_edges)
